import React, { useEffect, useState } from "react";
import AdminNavbar from "../Components/AdminNavbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/AdminPages.css";

const SubscriptionData = () => {
  const [subs, setSubs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/admin/subscription-data`)
      .then(res => res.json())
      .then(data => {
        setSubs(data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching subscription data:", err);
        setLoading(false);
      });
  }, []);

  return (
    <div className="dashboard-wrapper" style={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <AdminNavbar />
      <main className="dashboard-main" style={{ flex: 1, padding: "40px" }}>
        <h2>Raw Subscription Table Data</h2>
        {loading ? (
          <p>Loading...</p>
        ) : (
          <div className="subscriptions-grid">
            {subs.map((s) => (
              <div key={s.id} className="favorite-card">
                <p><strong>ID:</strong> {s.id}</p>
                <p><strong>User ID:</strong> {s.user_id}</p>
                <p><strong>Plan:</strong> {s.plan_name}</p>
                <p><strong>Active:</strong> {s.active ? "Yes" : "No"}</p>
                <p><strong>Delivery:</strong> {s.estimated_delivery ? new Date(s.estimated_delivery).toLocaleString() : "N/A"}</p>
                <p><strong>Created At:</strong> {new Date(s.created_at).toLocaleString()}</p>
                <p><strong>Shipping Info:</strong> <pre>{JSON.stringify(s.shipping_info, null, 2)}</pre></p>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default SubscriptionData;
